import sqlite3
import math
from typing import List, Dict, Any, Tuple

# ---------- Fixed configuration (as required) ----------
sqlite_paths = {
    "business": "D:/Yelp-JSON/db/sqlite3/business.db",
    "checkin": "D:/Yelp-JSON/db/sqlite3/checkin.db",
    "photo": "D:/Yelp-JSON/db/sqlite3/photo.db",
    "review": "D:/Yelp-JSON/db/sqlite3/review.db",
    "tip": "D:/Yelp-JSON/db/sqlite3/tip.db",
    "user": "D:/Yelp-JSON/db/sqlite3/user.db"
}

config = {
    'milvus_collections': {
        'reviews': 'reviews',          # review的text存储成向量在reviews这个collection里面
        'photos': 'photo_vector',      # photo存储在photo_vector里面
        'tips': 'milvus_tip'           # tip的text存储在milvus_tip这个collection里面
    },
    'milvus_host': 'localhost',
    'milvus_port': '19530',
    'neo4j_uri': 'bolt://localhost:7687',
    'neo4j_auth': ('neo4j', 'password')
}

# ---------- Helpers ----------

def dict_factory(cursor, row):
    d = {}
    for idx, col in enumerate(cursor.description):
        d[col[0]] = row[idx]
    return d


def chunked(lst: List[Any], n: int):
    for i in range(0, len(lst), n):
        yield lst[i:i+n]


def safe_norm(x: float, lo: float, hi: float) -> float:
    if x is None:
        return 0.0
    if hi <= lo:
        return 0.0
    return max(0.0, min(1.0, (x - lo) / (hi - lo)))


def try_import_milvus():
    try:
        from pymilvus import connections, Collection, utility
        return connections, Collection, utility
    except Exception:
        return None, None, None


def try_import_neo4j():
    try:
        from neo4j import GraphDatabase
        return GraphDatabase
    except Exception:
        return None


def try_import_sentence_transformers():
    try:
        from sentence_transformers import SentenceTransformer
        return SentenceTransformer
    except Exception:
        return None


def pick_embedding_model(dim: int):
    """Pick a common SentenceTransformer model that matches collection vector dim."""
    SentenceTransformer = try_import_sentence_transformers()
    if SentenceTransformer is None:
        raise RuntimeError("sentence-transformers not installed. pip install sentence-transformers")

    # Common dims: 384 (MiniLM), 768 (mpnet / bert-base)
    if dim == 384:
        return SentenceTransformer('sentence-transformers/all-MiniLM-L6-v2')
    if dim == 768:
        return SentenceTransformer('sentence-transformers/all-mpnet-base-v2')

    # Fallback: try mpnet then error if mismatch
    model = SentenceTransformer('sentence-transformers/all-mpnet-base-v2')
    if model.get_sentence_embedding_dimension() != dim:
        raise RuntimeError(f"No default model for dim={dim}. Please use an embedding model matching Milvus dim.")
    return model


def milvus_search_business_scores(
    collection_name: str,
    query_text: str,
    candidate_business_ids: List[str],
    topk: int = 200,
    business_id_field: str = 'business_id',
    vector_field: str = 'embedding',
    output_fields: List[str] = None,
) -> Dict[str, List[float]]:
    """Return per-business list of similarity scores from Milvus search hits."""
    connections, Collection, utility = try_import_milvus()
    if connections is None:
        raise RuntimeError("pymilvus not installed or import failed. pip install pymilvus")

    connections.connect(host=config['milvus_host'], port=config['milvus_port'])

    if not utility.has_collection(collection_name):
        raise RuntimeError(f"Milvus collection not found: {collection_name}")

    col = Collection(collection_name)
    col.load()

    # detect vector dim
    vec_dim = None
    for f in col.schema.fields:
        if f.name == vector_field:
            # For FloatVector, params may include dim
            vec_dim = int(f.params.get('dim')) if hasattr(f, 'params') and f.params and 'dim' in f.params else None
    if vec_dim is None:
        # fallback: attempt from schema json if available
        try:
            vec_dim = int(col.schema.to_dict()['fields_dict'][vector_field]['params']['dim'])
        except Exception:
            raise RuntimeError(f"Cannot determine vector dim for field '{vector_field}' in {collection_name}.")

    model = pick_embedding_model(vec_dim)
    qvec = model.encode([query_text], normalize_embeddings=True).tolist()

    if output_fields is None:
        output_fields = [business_id_field]

    # Build expr if feasible
    expr = None
    try:
        if candidate_business_ids and len(candidate_business_ids) <= 1000:
            # Milvus expr for VarChar list: business_id in ["..",".."]
            quoted = ','.join([f'"{bid}"' for bid in candidate_business_ids])
            expr = f"{business_id_field} in [{quoted}]"
    except Exception:
        expr = None

    # Metric handling: assume COSINE/IP common; rely on collection index/metric.
    # If metric is COSINE and vectors are normalized, score behaves like cosine similarity.
    res = col.search(
        data=qvec,
        anns_field=vector_field,
        param={"nprobe": 16},
        limit=topk,
        expr=expr,
        output_fields=output_fields
    )

    scores_by_bid: Dict[str, List[float]] = {}
    # res is a list (nq) of hits
    for hits in res:
        for h in hits:
            try:
                bid = h.entity.get(business_id_field)
            except Exception:
                # Some pymilvus versions use h.get
                bid = h.get(business_id_field, None)
            if not bid:
                continue
            if candidate_business_ids and bid not in set(candidate_business_ids):
                # if we didn't filter in expr
                continue
            scores_by_bid.setdefault(bid, []).append(float(h.score))

    return scores_by_bid


def aggregate_topk(scores_by_bid: Dict[str, List[float]], k: int = 3) -> Dict[str, float]:
    out = {}
    for bid, scores in scores_by_bid.items():
        if not scores:
            out[bid] = 0.0
            continue
        top = sorted(scores, reverse=True)[:k]
        out[bid] = sum(top) / len(top)
    return out


def keyword_fallback_vibe(review_conn: sqlite3.Connection, business_ids: List[str]) -> Tuple[Dict[str, float], Dict[str, float]]:
    """Fallback when Milvus unavailable: count keyword hits in reviews for deep-dish and vibe."""
    deep_kw = ["deep dish", "deep-dish", "chicago style", "detroit style"]
    vibe_kw = ["classic", "old school", "hearty", "cozy", "comfort", "comfort food", "nostalgic", "traditional"]

    deep_score = {bid: 0.0 for bid in business_ids}
    vibe_score = {bid: 0.0 for bid in business_ids}

    review_conn.row_factory = dict_factory
    cur = review_conn.cursor()

    # SQLite parameter limit -> chunk
    for chunk in chunked(business_ids, 800):
        placeholders = ','.join(['?'] * len(chunk))
        # Sample recent-ish reviews: if table has date, you can order; keep simple
        rows = cur.execute(
            f"SELECT business_id, text FROM review WHERE business_id IN ({placeholders})",
            chunk
        ).fetchall()
        for r in rows:
            bid = r['business_id']
            txt = (r.get('text') or '').lower()
            deep_hits = sum(1 for k in deep_kw if k in txt)
            vibe_hits = sum(1 for k in vibe_kw if k in txt)
            deep_score[bid] += deep_hits
            vibe_score[bid] += vibe_hits

    # log-scale normalize-ish
    for bid in business_ids:
        deep_score[bid] = math.log1p(deep_score[bid])
        vibe_score[bid] = math.log1p(vibe_score[bid])

    return deep_score, vibe_score


def neo4j_enrich_categories(business_ids: List[str]) -> Dict[str, List[str]]:
    GraphDatabase = try_import_neo4j()
    if GraphDatabase is None:
        return {}

    out: Dict[str, List[str]] = {}
    try:
        driver = GraphDatabase.driver(config['neo4j_uri'], auth=config['neo4j_auth'])
    except Exception:
        return {}

    cypher = (
        "MATCH (b:Business {business_id:$bid})-[:IN_CATEGORY]->(c:Category) "
        "RETURN collect(c.name) AS categories"
    )

    try:
        with driver.session() as session:
            for bid in business_ids:
                try:
                    rec = session.run(cypher, bid=bid).single()
                    if rec and rec.get('categories'):
                        out[bid] = [str(x) for x in rec['categories'] if x is not None]
                except Exception:
                    # schema might not match
                    continue
    finally:
        try:
            driver.close()
        except Exception:
            pass

    return out


def main():
    city = "Sparks"
    state = None  # set to "NV" if you want stricter filter

    # --- Step 1: SQLite candidates ---
    biz_conn = sqlite3.connect(sqlite_paths['business'])
    biz_conn.row_factory = dict_factory
    bcur = biz_conn.cursor()

    sql = (
        "SELECT business_id, name, address, city, state, postal_code, stars, review_count, categories "
        "FROM business "
        "WHERE city=? AND categories LIKE '%Pizza%' "
    )
    params = [city]
    if state:
        sql += " AND state=? "
        params.append(state)
    sql += " ORDER BY stars DESC, review_count DESC LIMIT 300"

    candidates = bcur.execute(sql, params).fetchall()
    if not candidates:
        print(f"No pizza candidates found in {city}.")
        return

    candidate_ids = [c['business_id'] for c in candidates]

    # --- Step 2: rating aggregation from review.db ---
    rev_conn = sqlite3.connect(sqlite_paths['review'])
    rev_conn.row_factory = dict_factory
    rcur = rev_conn.cursor()

    rating_agg: Dict[str, Dict[str, float]] = {}
    for chunk in chunked(candidate_ids, 800):
        placeholders = ','.join(['?'] * len(chunk))
        q = (
            f"SELECT business_id, AVG(stars) AS avg_review_stars, COUNT(*) AS n_reviews "
            f"FROM review WHERE business_id IN ({placeholders}) GROUP BY business_id"
        )
        for row in rcur.execute(q, chunk).fetchall():
            rating_agg[row['business_id']] = {
                'avg_review_stars': float(row['avg_review_stars']) if row['avg_review_stars'] is not None else None,
                'n_reviews': float(row['n_reviews']) if row['n_reviews'] is not None else 0.0,
            }

    # --- Step 3: Milvus semantic scoring (deep-dish + vibe) ---
    deepdish_score: Dict[str, float] = {bid: 0.0 for bid in candidate_ids}
    vibe_score: Dict[str, float] = {bid: 0.0 for bid in candidate_ids}

    use_milvus = True
    try:
        # Query texts
        q_deep = "deep dish pizza chicago style thick crust"
        q_vibe = "classic hearty vibe old school cozy traditional comfort food"

        # Search reviews
        review_col = config['milvus_collections']['reviews']
        tip_col = config['milvus_collections']['tips']

        deep_reviews = milvus_search_business_scores(
            collection_name=review_col,
            query_text=q_deep,
            candidate_business_ids=candidate_ids,
            topk=400,
            business_id_field='business_id',
            vector_field='embedding',
            output_fields=['business_id']
        )
        vibe_reviews = milvus_search_business_scores(
            collection_name=review_col,
            query_text=q_vibe,
            candidate_business_ids=candidate_ids,
            topk=400,
            business_id_field='business_id',
            vector_field='embedding',
            output_fields=['business_id']
        )

        # Search tips (optional)
        try:
            deep_tips = milvus_search_business_scores(
                collection_name=tip_col,
                query_text=q_deep,
                candidate_business_ids=candidate_ids,
                topk=200,
                business_id_field='business_id',
                vector_field='embedding',
                output_fields=['business_id']
            )
            vibe_tips = milvus_search_business_scores(
                collection_name=tip_col,
                query_text=q_vibe,
                candidate_business_ids=candidate_ids,
                topk=200,
                business_id_field='business_id',
                vector_field='embedding',
                output_fields=['business_id']
            )
        except Exception:
            deep_tips, vibe_tips = {}, {}

        deepdish_score_reviews = aggregate_topk(deep_reviews, k=3)
        vibe_score_reviews = aggregate_topk(vibe_reviews, k=3)
        deepdish_score_tips = aggregate_topk(deep_tips, k=2) if deep_tips else {}
        vibe_score_tips = aggregate_topk(vibe_tips, k=2) if vibe_tips else {}

        for bid in candidate_ids:
            # Combine review+tip semantic evidence
            deepdish_score[bid] = 0.7 * deepdish_score_reviews.get(bid, 0.0) + 0.3 * deepdish_score_tips.get(bid, 0.0)
            vibe_score[bid] = 0.7 * vibe_score_reviews.get(bid, 0.0) + 0.3 * vibe_score_tips.get(bid, 0.0)

    except Exception as e:
        use_milvus = False
        print("Milvus semantic search unavailable; using keyword fallback. Reason:", str(e))
        deepdish_score, vibe_score = keyword_fallback_vibe(rev_conn, candidate_ids)

    # --- Step 4: rank ---
    # Build a combined table
    rows = []
    for c in candidates:
        bid = c['business_id']
        agg = rating_agg.get(bid, {})
        avg_review_stars = agg.get('avg_review_stars', None)
        n_reviews = agg.get('n_reviews', 0.0)

        rows.append({
            **c,
            'avg_review_stars': avg_review_stars if avg_review_stars is not None else c.get('stars'),
            'n_reviews': n_reviews,
            'deepdish_score': float(deepdish_score.get(bid, 0.0)),
            'vibe_score': float(vibe_score.get(bid, 0.0))
        })

    # Prefer deep-dish evidence: take top by deepdish_score first
    rows_sorted_deep = sorted(rows, key=lambda x: x['deepdish_score'], reverse=True)
    shortlist = rows_sorted_deep[:25] if len(rows_sorted_deep) > 25 else rows_sorted_deep

    # Normalize within shortlist for blending
    avg_stars_vals = [r['avg_review_stars'] for r in shortlist if r['avg_review_stars'] is not None]
    vibe_vals = [r['vibe_score'] for r in shortlist]
    deep_vals = [r['deepdish_score'] for r in shortlist]

    s_lo, s_hi = (min(avg_stars_vals), max(avg_stars_vals)) if avg_stars_vals else (0.0, 5.0)
    v_lo, v_hi = (min(vibe_vals), max(vibe_vals)) if vibe_vals else (0.0, 1.0)
    d_lo, d_hi = (min(deep_vals), max(deep_vals)) if deep_vals else (0.0, 1.0)

    for r in shortlist:
        s = safe_norm(r['avg_review_stars'] if r['avg_review_stars'] is not None else 0.0, s_lo, s_hi)
        v = safe_norm(r['vibe_score'], v_lo, v_hi)
        d = safe_norm(r['deepdish_score'], d_lo, d_hi)
        # Blend: rating first, then vibe, then deep-dish (deep-dish already enforced by shortlist)
        r['final_score'] = 0.55 * s + 0.25 * v + 0.20 * d

    final_ranked = sorted(shortlist, key=lambda x: (x['final_score'], x.get('n_reviews', 0.0)), reverse=True)[:10]

    # --- Step 5: optional Neo4j enrichment ---
    enrich = neo4j_enrich_categories([r['business_id'] for r in final_ranked])

    # --- Output ---
    print(f"Top deep-dish-ish pizza places in {city} (ranked by rating + classic/hearty vibe):\n")
    for i, r in enumerate(final_ranked, 1):
        cats = enrich.get(r['business_id'])
        cats_str = ("; ".join(cats[:8]) + (" ..." if cats and len(cats) > 8 else "")) if cats else (r.get('categories') or "")

        print(f"{i}. {r['name']}")
        print(f"   Address: {r.get('address','')}, {r.get('city','')}, {r.get('state','')} {r.get('postal_code','')}")
        print(f"   Avg review stars: {r.get('avg_review_stars')} | Reviews: {int(r.get('n_reviews', 0))}")
        if use_milvus:
            print(f"   Deep-dish semantic score: {r['deepdish_score']:.4f} | Vibe semantic score: {r['vibe_score']:.4f}")
        else:
            print(f"   Deep-dish keyword score: {r['deepdish_score']:.4f} | Vibe keyword score: {r['vibe_score']:.4f}")
        if cats_str:
            print(f"   Categories: {cats_str}")
        print()

    # Close connections
    try:
        biz_conn.close()
    except Exception:
        pass
    try:
        rev_conn.close()
    except Exception:
        pass


if __name__ == "__main__":
    main()

