import json
import math
import re
import sqlite3
from dataclasses import dataclass
from typing import Any, Dict, List, Optional, Tuple

# --------- Fixed configuration (must match prompt) ---------
sqlite_paths = {
    "business": "D:/Yelp-JSON/db/sqlite3/business.db",
    "checkin": "D:/Yelp-JSON/db/sqlite3/checkin.db",
    "photo": "D:/Yelp-JSON/db/sqlite3/photo.db",
    "review": "D:/Yelp-JSON/db/sqlite3/review.db",
    "tip": "D:/Yelp-JSON/db/sqlite3/tip.db",
    "user": "D:/Yelp-JSON/db/sqlite3/user.db"
}

milvus_cfg = {
    'milvus_collections': {
        'reviews': 'reviews',
        'photos': 'photo_vector',
        'tips': 'milvus_tip'
    },
    'milvus_host': 'localhost',
    'milvus_port': '19530'
}

neo4j_cfg = {
    'neo4j_uri': 'bolt://localhost:7687',
    'neo4j_auth': ('neo4j', 'password')
}

# --------- Helpers: SQLite schema probing ---------

def sqlite_connect(path: str) -> sqlite3.Connection:
    conn = sqlite3.connect(path)
    conn.row_factory = sqlite3.Row
    return conn


def table_exists(conn: sqlite3.Connection, table: str) -> bool:
    cur = conn.execute("SELECT name FROM sqlite_master WHERE type='table' AND name=?", (table,))
    return cur.fetchone() is not None


def get_columns(conn: sqlite3.Connection, table: str) -> List[str]:
    try:
        cur = conn.execute(f"PRAGMA table_info({table})")
        return [r[1] for r in cur.fetchall()]
    except Exception:
        return []


def first_existing_table(conn: sqlite3.Connection, candidates: List[str]) -> Optional[str]:
    for t in candidates:
        if table_exists(conn, t):
            return t
    return None

# --------- Hours parsing ---------

_time_re = re.compile(r"^(\d{1,2}):(\d{2})$")

def parse_hhmm(s: str) -> Optional[int]:
    """Return minutes since 00:00."""
    if not s or not isinstance(s, str):
        return None
    m = _time_re.match(s.strip())
    if not m:
        return None
    hh = int(m.group(1))
    mm = int(m.group(2))
    if hh < 0 or hh > 23 or mm < 0 or mm > 59:
        return None
    return hh * 60 + mm


def open_past_midnight_from_hours_obj(hours_obj: Any, latest_cutoff_min: int = 6 * 60) -> bool:
    """
    Yelp hours often: {"Monday": "11:00-02:00", ...}
    We treat as open past midnight if:
      - close time is numerically < open time (crosses midnight), OR
      - close is between 00:00 and 05:59 (configurable) even if open missing.
    """
    if not hours_obj:
        return False

    if isinstance(hours_obj, str):
        try:
            hours_obj = json.loads(hours_obj)
        except Exception:
            # If it's a freeform string, try to detect patterns like "11:00-02:00"
            parts = re.findall(r"(\d{1,2}:\d{2})\s*-\s*(\d{1,2}:\d{2})", hours_obj)
            for op, cl in parts:
                opm, clm = parse_hhmm(op), parse_hhmm(cl)
                if opm is None or clm is None:
                    continue
                if clm < opm:
                    return True
                if 0 <= clm < latest_cutoff_min:
                    return True
            return False

    if not isinstance(hours_obj, dict):
        return False

    for _, span in hours_obj.items():
        if not span or not isinstance(span, str) or '-' not in span:
            continue
        op, cl = [x.strip() for x in span.split('-', 1)]
        opm, clm = parse_hhmm(op), parse_hhmm(cl)
        if opm is None or clm is None:
            continue
        # crosses midnight
        if clm < opm:
            return True
        # explicit after-midnight close time
        if 0 <= clm < latest_cutoff_min:
            return True
    return False

# --------- Milvus vector search ---------

@dataclass
class VectorHit:
    business_id: str
    score: float
    text: str
    source: str  # 'review' or 'tip'


def get_query_embedding(text: str) -> Optional[List[float]]:
    """Embed query using SentenceTransformers; return None if not available."""
    try:
        from sentence_transformers import SentenceTransformer
        model = SentenceTransformer("all-MiniLM-L6-v2")
        emb = model.encode([text], normalize_embeddings=True)[0]
        return emb.tolist() if hasattr(emb, 'tolist') else list(emb)
    except Exception as e:
        print("[WARN] Cannot build embedding via sentence-transformers:", e)
        return None


def milvus_search(collection_name: str, query_emb: List[float], top_k: int, anns_field_candidates: List[str]) -> List[Dict[str, Any]]:
    """Return raw result dicts with keys: business_id, text, score."""
    try:
        from pymilvus import connections, Collection, utility

        connections.connect(host=milvus_cfg['milvus_host'], port=milvus_cfg['milvus_port'])
        if not utility.has_collection(collection_name):
            print(f"[WARN] Milvus collection not found: {collection_name}")
            return []

        col = Collection(collection_name)
        col.load()

        # Guess vector field name
        schema_fields = [f.name for f in col.schema.fields]
        anns_field = None
        for c in anns_field_candidates:
            if c in schema_fields:
                anns_field = c
                break
        if anns_field is None:
            # best-effort: find first float vector field
            for f in col.schema.fields:
                if str(f.dtype).lower().find('vector') >= 0:
                    anns_field = f.name
                    break
        if anns_field is None:
            print(f"[WARN] No vector field found in Milvus collection {collection_name}. Fields={schema_fields}")
            return []

        # Guess output fields
        output_fields = []
        for cand in ["business_id", "biz_id", "business", "store_id"]:
            if cand in schema_fields:
                output_fields.append(cand)
                break
        for cand in ["text", "content", "review_text", "tip_text"]:
            if cand in schema_fields:
                output_fields.append(cand)
                break

        search_params = {"metric_type": "IP", "params": {"nprobe": 16}}

        res = col.search(
            data=[query_emb],
            anns_field=anns_field,
            param=search_params,
            limit=top_k,
            output_fields=output_fields
        )

        hits = []
        for h in res[0]:
            ent = getattr(h, "entity", None)
            # For newer pymilvus, use h.entity.get(field)
            def ent_get(field: str):
                if ent is None:
                    return None
                try:
                    return ent.get(field)
                except Exception:
                    try:
                        return ent[field]
                    except Exception:
                        return None

            biz = None
            txt = ""
            for cand in ["business_id", "biz_id", "business", "store_id"]:
                if cand in output_fields:
                    biz = ent_get(cand)
                    break
            for cand in ["text", "content", "review_text", "tip_text"]:
                if cand in output_fields:
                    txt = ent_get(cand) or ""
                    break
            if biz is None:
                continue

            # With IP, higher is better. If your collection uses L2, you may want to invert.
            score = float(getattr(h, "score", 0.0))
            hits.append({"business_id": str(biz), "text": str(txt)[:400], "score": score})

        return hits

    except Exception as e:
        print(f"[WARN] Milvus search failed for {collection_name}:", e)
        return []

# --------- Main pipeline ---------

def main(top_n: int = 10):
    query_text = (
        "Boise late-night work-friendly place open past midnight with good WiFi, "
        "quiet but not dull atmosphere; laptop-friendly, outlets, studying, productive vibe"
    )

    # 1) SQLite: fetch Boise candidates
    bconn = sqlite_connect(sqlite_paths["business"])

    # Detect business table name
    business_table = first_existing_table(bconn, ["business", "yelp_business", "businesses"]) 
    if business_table is None:
        raise RuntimeError("Cannot find a business table in business.db")

    cols = set(get_columns(bconn, business_table))

    # Required columns mapping (best-effort)
    def pick_col(*names):
        for n in names:
            if n in cols:
                return n
        return None

    col_business_id = pick_col("business_id", "biz_id")
    col_name = pick_col("name")
    col_city = pick_col("city")
    col_state = pick_col("state")
    col_address = pick_col("address")
    col_postal = pick_col("postal_code", "zip_code")
    col_is_open = pick_col("is_open", "open")
    col_stars = pick_col("stars", "rating")
    col_review_count = pick_col("review_count")
    col_categories = pick_col("categories")
    col_hours = pick_col("hours")
    col_attributes = pick_col("attributes")

    if not all([col_business_id, col_name, col_city]):
        raise RuntimeError(f"Business table missing required columns. Found columns: {sorted(cols)}")

    # Category prefilter keywords (wide net)
    cat_keywords = ["Coffee", "Cafe", "Cafes", "Tea", "Restaurant", "Bars", "Bar", "Diner", "Pizza", "Bakery", "Boba", "Cowork", "Co-work"]

    where = [f"{col_city} = ?"]
    params: List[Any] = ["Boise"]
    if col_is_open:
        where.append(f"{col_is_open} = 1")

    if col_categories:
        where.append("(" + " OR ".join([f"{col_categories} LIKE ?" for _ in cat_keywords]) + ")")
        params.extend([f"%{k}%" for k in cat_keywords])

    select_fields = [
        col_business_id, col_name,
        col_address or "NULL as address",
        col_city,
        col_state or "NULL as state",
        col_postal or "NULL as postal_code",
        col_stars or "NULL as stars",
        col_review_count or "NULL as review_count",
        col_categories or "NULL as categories",
        col_hours or "NULL as hours",
        col_attributes or "NULL as attributes",
    ]

    sql = f"SELECT {', '.join(select_fields)} FROM {business_table} WHERE {' AND '.join(where)}"
    boise_rows = bconn.execute(sql, params).fetchall()

    # 2) Filter open past midnight
    candidates = []
    for r in boise_rows:
        hours_val = r["hours"] if "hours" in r.keys() else None
        if col_hours and open_past_midnight_from_hours_obj(hours_val):
            candidates.append(r)

    # If hours column not present or yields none, try normalized hours table
    if len(candidates) == 0:
        hours_table = first_existing_table(bconn, ["business_hours", "hours", "yelp_hours"]) 
        if hours_table:
            hcols = set(get_columns(bconn, hours_table))
            hb = None
            for x in ["business_id", "biz_id"]:
                if x in hcols:
                    hb = x
                    break
            hopen = "open" if "open" in hcols else None
            hclose = "close" if "close" in hcols else None
            if hb and hclose and hopen:
                # Get businesses that close after midnight (cross-midnight or close between 00:00 and 05:59)
                q = f"""
                SELECT DISTINCT b.*
                FROM {business_table} b
                JOIN {hours_table} h ON b.{col_business_id} = h.{hb}
                WHERE b.{col_city}=?
                {f"AND b.{col_is_open}=1" if col_is_open else ""}
                AND (
                    time(h.{hclose}) < time(h.{hopen})
                    OR (time(h.{hclose}) >= time('00:00') AND time(h.{hclose}) <= time('05:59'))
                )
                """
                candidates = bconn.execute(q, ["Boise"]).fetchall()

    if len(candidates) == 0:
        print("No Boise businesses matched 'open past midnight' based on available hours data.")
        print("Tip: verify hours schema/content in business.db.")
        return

    candidate_ids = {str(r[col_business_id]) for r in candidates}

    # 3) Milvus semantic retrieval (reviews + tips)
    q_emb = get_query_embedding(query_text)
    hits: List[VectorHit] = []

    if q_emb is not None:
        review_raw = milvus_search(
            milvus_cfg['milvus_collections']['reviews'],
            q_emb,
            top_k=200,
            anns_field_candidates=["embedding", "vector", "review_embedding", "emb"]
        )
        tip_raw = milvus_search(
            milvus_cfg['milvus_collections']['tips'],
            q_emb,
            top_k=200,
            anns_field_candidates=["embedding", "vector", "tip_embedding", "emb"]
        )

        for d in review_raw:
            if d["business_id"] in candidate_ids:
                hits.append(VectorHit(d["business_id"], d["score"], d.get("text", ""), "review"))
        for d in tip_raw:
            if d["business_id"] in candidate_ids:
                hits.append(VectorHit(d["business_id"], d["score"], d.get("text", ""), "tip"))
    else:
        print("[WARN] No query embedding available; skipping Milvus semantic rerank.")

    # 4) Aggregate + rank
    # Semantic score: sum of top few scores per business
    per_biz: Dict[str, Dict[str, Any]] = {}
    for r in candidates:
        bid = str(r[col_business_id])
        per_biz[bid] = {
            "business_id": bid,
            "name": r[col_name],
            "address": (r["address"] if "address" in r.keys() else None),
            "city": r[col_city],
            "state": (r["state"] if "state" in r.keys() else None),
            "postal_code": (r["postal_code"] if "postal_code" in r.keys() else (r["zip_code"] if "zip_code" in r.keys() else None)),
            "stars": float(r["stars"]) if "stars" in r.keys() and r["stars"] is not None else None,
            "review_count": int(r["review_count"]) if "review_count" in r.keys() and r["review_count"] is not None else 0,
            "categories": r["categories"] if "categories" in r.keys() else None,
            "hours": r["hours"] if "hours" in r.keys() else None,
            "semantic_score": 0.0,
            "evidence": []
        }

    # Keep evidence snippets
    hits_by_biz: Dict[str, List[VectorHit]] = {}
    for h in hits:
        hits_by_biz.setdefault(h.business_id, []).append(h)

    for bid, lst in hits_by_biz.items():
        lst_sorted = sorted(lst, key=lambda x: x.score, reverse=True)
        top_lst = lst_sorted[:6]
        sem = sum(x.score for x in top_lst)
        per_biz[bid]["semantic_score"] = sem
        per_biz[bid]["evidence"] = [
            {"source": x.source, "score": x.score, "text": x.text}
            for x in top_lst
            if x.text
        ]

    # Final score combines semantic + stars + popularity
    # If no semantic hits (Milvus down), ranking will rely on stars and review_count.
    def final_score(item: Dict[str, Any]) -> float:
        stars = item["stars"] if item["stars"] is not None else 0.0
        rc = item["review_count"] or 0
        sem = item["semantic_score"] or 0.0
        return (sem * 1.0) + (stars * 0.8) + (math.log1p(rc) * 0.2)

    results = list(per_biz.values())
    results.sort(key=final_score, reverse=True)

    # Output
    print(f"Found {len(results)} Boise places open past midnight (after filtering). Showing top {top_n}:\n")
    for i, it in enumerate(results[:top_n], 1):
        addr = it.get("address") or ""
        loc = ", ".join([x for x in [it.get("city"), it.get("state"), it.get("postal_code")] if x])
        print(f"#{i} {it['name']}  | stars={it.get('stars')}  reviews={it.get('review_count')}  sem={it.get('semantic_score'):.3f}")
        if addr or loc:
            print(f"   {addr} {loc}".strip())
        if it.get("categories"):
            print(f"   categories: {it['categories']}")
        # Show up to 2 evidence snippets
        ev = it.get("evidence", [])[:2]
        if ev:
            print("   evidence:")
            for e in ev:
                txt = e["text"].replace("\n", " ").strip()
                print(f"     - ({e['source']}, score={e['score']:.3f}) {txt[:220]}")
        print()


if __name__ == "__main__":
    try:
        main(top_n=10)
    except Exception as ex:
        print("[ERROR]", ex)

